const $=s=>document.querySelector(s);
const stations={shinjuku:{name:'新宿',en:'Shinjuku',lines:['JR 山手線','東京 Metro 丸之內線','小田急線','京王線']},tokyo:{name:'東京',en:'Tokyo',lines:['JR 山手線','東京 Metro 丸之內線','JR 中央線','JR 京葉線']},shibuya:{name:'澀谷',en:'Shibuya',lines:['JR 山手線','東京 Metro 銀座線','東京 Metro 半藏門線','東急東橫線']},ueno:{name:'上野',en:'Ueno',lines:['JR 山手線','東京 Metro 銀座線','東京 Metro 日比谷線','JR 常磐線']},ikebukuro:{name:'池袋',en:'Ikebukuro',lines:['JR 山手線','東京 Metro 丸之內線','東京 Metro 有樂町線','西武池袋線']}};
let active={station:'shinjuku',from:'JR 山手線',to:'東京 Metro 丸之內線'},step=0,accessible=false,saved=[];
try{saved=JSON.parse(localStorage.getItem('norikae-saved')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(r=>stations[r.station]&&stations[r.station].lines.includes(r.from)&&stations[r.station].lines.includes(r.to));}catch{}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function modal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
function options(){const s=stations[$('#station').value];for(const id of ['from','to'])$('#'+id).innerHTML=s.lines.map(l=>`<option>${l}</option>`).join('');$('#to').selectedIndex=1}
function steps(){return [{title:'下車後，先找轉乘指標',short:'月台出發',image:'platform.jpg',arrow:'↑',body:`從 ${active.from} 下車，先停下來確認「${active.to}」的路線名稱與方向。`,tip:'示意照片不一定來自所選車站。下車位置會影響路徑，請先查看月台上的轉乘指標，不要只跟著人群走。'},{title:accessible?'尋找電梯，前往轉乘樓層':'沿指標前往轉乘通道',short:accessible?'搭乘電梯':'前往通道',image:accessible?'platform.jpg':'passage.jpg',arrow:'↑',body:accessible?'辨識電梯圖示，確認可到達的樓層。此模式展示電梯優先的模擬流程。':'依轉乘指標前往樓梯或手扶梯，進入站內通道。先確認箭頭，再往前走。',tip:accessible?'照片僅作環境示意，並非電梯位置紀錄。實際電梯位置、服務狀態與無障礙動線請向站務人員確認。':'大型車站可能有不同閘口與出口。請找轉乘路線的名稱；出口指標不一定代表轉乘方向。'},{title:'認路線顏色，也確認名稱',short:'辨識指標',image:'signs.jpg',arrow:'↗',body:`在通道分岔處，確認「${active.to}」名稱與箭頭，繼續前往乘車區。`,tip:'不同營運公司的轉乘可能需要出閘再入閘。這個示範未判定票價與閘口，請依實際票券與現場指示通行。'},{title:'確認方向，準備下一段旅程',short:'抵達月台',image:'platform.jpg',arrow:'↓',body:`抵達 ${active.to} 乘車區後，核對目的地、行車方向與月台電子看板。`,tip:'同一條路線可能有不同方向、快慢車或直通運轉。請依目的地確認班次；本網站不提供即時列車資訊。'}]}
function renderStep(){const data=steps(),s=data[step];$('#stepPhoto').src='assets/'+s.image;$('#stepPhoto').alt=s.title+'：使用者提供的環境示意照片';$('#stepCounter').textContent=`STEP 0${step+1} / 04`;$('#stepKicker').textContent=`0${step+1} / ${s.short}`;$('#stepTitle').textContent=s.title;$('#stepDescription').textContent=s.body;$('#photoArrow').textContent=s.arrow;$('#prev').disabled=step===0;$('#next').textContent=step===3?'完成導覽 ✓':'下一步 →';$('#stepTrack').innerHTML=data.map((s,i)=>`<button data-step="${i}" class="${i===step?'active':''}"><b>${i+1}</b>${s.short}</button>`).join('');document.querySelectorAll('.map-node').forEach((n,i)=>n.classList.toggle('active',i===step));document.querySelectorAll('[data-step]').forEach(n=>{n.onclick=()=>{step=Number(n.dataset.step);renderStep()};n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();n.click()}}})}
function key(r){return [r.station,r.from,r.to].join('|')}
function savedState(){$('#savedCount').textContent=saved.length;$('#save').textContent=saved.some(r=>key(r)===key(active))?'♥ 已收藏':'♡ 收藏路線'}
function render(){const s=stations[active.station];$('#routeTitle').innerHTML=`${s.name}站 <small>${s.en} Station</small>`;$('#fromName').textContent=active.from;$('#toName').textContent=active.to;$('#toBadge').textContent=active.to.includes('丸之內')?'M':active.to.includes('銀座')?'G':active.to.includes('JR')?'JR':'●';$('#mapCaption').textContent=`${s.name}站・站內轉乘示意`;$('#minutes').textContent=accessible?'12':'8';$('#distance').textContent=accessible?'450':'350';$('#liftLabel').textContent=accessible?'電梯（模擬）':'樓梯／手扶梯';$('#routePath').style.strokeDasharray=accessible?'10 4':'';savedState();renderStep()}
$('#station').onchange=options;$('#swap').onclick=()=>{const a=$('#from').value;$('#from').value=$('#to').value;$('#to').value=a};$('#search').onclick=()=>{if($('#from').value===$('#to').value)return toast('請選擇兩條不同的路線');active={station:$('#station').value,from:$('#from').value,to:$('#to').value};step=0;render();toast('已更新轉乘模擬路線')};
function selectStation(id){$('#station').value=id;options();$('#search').click()}
document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>selectStation(b.dataset.station));$('#accessible').onchange=e=>{accessible=e.target.checked;render();toast(accessible?'已切換電梯優先模擬動線':'已切換一般模擬動線')};$('#prev').onclick=()=>{if(step>0){step--;renderStep()}};$('#next').onclick=()=>{if(step<3){step++;renderStep()}else modal('<h2>下一段旅程，準備出發。</h2><p>你已完成這條路線的 4 步模擬導覽。實際乘車前，記得再確認月台、列車方向與目的地。</p><button class="primary" id="restart">重新練習 →</button>'),$('#restart')&&($('#restart').onclick=()=>{$('#modal').close();step=0;renderStep()})};
$('#save').onclick=()=>{const idx=saved.findIndex(r=>key(r)===key(active));if(idx>=0)saved.splice(idx,1);else saved.push({...active});try{localStorage.setItem('norikae-saved',JSON.stringify(saved));toast(idx>=0?'已取消收藏':'已收藏，保存在這個瀏覽器')}catch{toast('此瀏覽器無法保存，收藏暫存於本次使用')}savedState()};
$('#savedNav').onclick=()=>{modal(`<h2>我的收藏</h2><p>收藏儲存於目前使用的瀏覽器。</p><div class="modal-list">${saved.length?saved.map((r,i)=>`<button data-saved="${i}">${stations[r.station].name}站<small>${r.from} → ${r.to}</small></button>`).join(''):'<p>還沒有收藏路線。按下「收藏路線」，留住下一次需要的方向。</p>'}</div>`);document.querySelectorAll('[data-saved]').forEach(b=>b.onclick=()=>{active={...saved[Number(b.dataset.saved)]};$('#station').value=active.station;options();$('#from').value=active.from;$('#to').value=active.to;step=0;render();$('#modal').close()})};
$('#stationNav').onclick=()=>{modal(`<h2>探索東京車站</h2><p>選一站，開始練習轉乘。所有動線均為模擬示意。</p><div class="modal-list">${Object.entries(stations).map(([id,s])=>`<button data-pick="${id}">${s.name}站 · ${s.en}<small>${s.lines.join(' / ')}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selectStation(b.dataset.pick);$('#modal').close()})};
$('#guideNav').onclick=()=>$('#route').scrollIntoView({behavior:'smooth'});$('#photoExpand').onclick=()=>modal(`<h2>${steps()[step].title}</h2><img src="assets/${steps()[step].image}" alt="使用者提供的車站環境示意照片"><p>照片示意：不代表所選車站的實際位置；請以現場指標為準。</p>`);$('#details').onclick=()=>modal(`<h2>${steps()[step].title}</h2><p>${steps()[step].body}</p><p>${steps()[step].tip}</p>`);$('#overview').onclick=()=>modal(`<h2>轉乘路線總覽</h2><p>${stations[active.station].name}站：${active.from} → ${active.to}</p><ol>${steps().map(s=>`<li><strong>${s.title}</strong><p>${s.body}</p></li>`).join('')}</ol><p>模擬流程，非車站實測動線。距離與時間僅作介面展示。</p>`);$('#mapTab').onclick=()=>{step=0;renderStep()};$('#tips').onclick=()=>modal('<h2>日本車站轉乘小筆記</h2><ol><li>先確認路線名稱，再看路線顏色與箭頭。</li><li>遇到分岔先看指標，分清楚「轉乘」與「出口」。</li><li>攜帶大件行李時，尋找電梯圖示或詢問站務人員。</li><li>到月台後，再核對列車的目的地與行車方向。</li></ol>');$('#about').onclick=()=>modal('<h2>轉乘的每一步，都有方向。</h2><p>選擇東京市區車站與兩條路線，再點選「查看轉乘路線」。點地圖數字或「下一步」，即可搭配照片練習轉乘流程。</p><p>這是互動示範版：各站共用抽象動線，未提供實測月台、樓層、票價或即時資訊。照片由使用者提供，作環境辨識示意，不代表所選路線的實際場景。</p><p>電梯優先為模擬流程，實際無障礙路線請向站務人員確認。</p>');options();render();
